import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import {fileURLToPath} from "node:url";
import {fixture,host} from "../../building-loop/test/helpers.mjs";
import {digest} from "../../building-loop/governance/policy.mjs";
import {QUALITY} from "../../building-loop/governance/preflight.mjs";

// Replay one frozen, actually observed search through the production handler.
// This is an isolated host-contract replay, not a paid model run or retroactive
// modification of the original final-review receipt.
const run=fileURLToPath(new URL("../../../outputs/building-loop-efficiency-audit/20261110T032313Z/",import.meta.url));
const workspace=path.join(run,"fresh/workspace");
const events=fs.readFileSync(path.join(run,"events.jsonl"),"utf8").trimEnd().split(/\r?\n/);
const call=JSON.parse(events[873]),result=JSON.parse(events[874]);
const args=JSON.parse(call.data.arguments);
const originalResult=JSON.parse(result.data.message.content.find(row=>row.type==="text").text);
const originalReceipt=JSON.parse(fs.readFileSync(path.join(workspace,"records/audit-final.json"),"utf8"));
assert.equal(call.type,"tool/call");assert.equal(call.data.name,"building_loop_file");
assert.deepEqual(args,{action:"search",path:"module/candidate.md",query:"sources/synthetic.md 第"});
const policy=JSON.parse(fs.readFileSync(path.join(workspace,"BUILDING-LOOP.json"),"utf8"));
assert.deepEqual(policy.units.K01.phases["first-review"].read,policy.units.K01.phases["final-review"].read,
  "The replay uses first-review activation with exactly the same authorized search scope as the original final-review.");
let output;
await fixture(async(root,write)=>{
  const files=new Set(["BUILDING-LOOP.json",...policy.instructions,...policy.ledgerContext,policy.units.K01.candidate,
    ...Object.values(policy.units.K01.phases).flatMap(p=>p.read)]);
  for(const pin of Object.values(policy.sourcePins))if(pin.observation?.file)files.add(pin.observation.file);
  for(const file of files)if(fs.existsSync(path.join(workspace,file))){
    fs.mkdirSync(path.dirname(path.join(root,file)),{recursive:true});write(file,fs.readFileSync(path.join(workspace,file)));
  }
  const h=host(root,{automaticCoverage:false});
  const executor=(await h.flow("root","advance")).childId;
  await h.flow(executor,"prepare");await h.flow(executor,"submit");
  const reviewer=(await h.flow("root","advance")).childId;
  await h.flow(reviewer,"prepare");
  const actual=await h.invoke(reviewer,"building_loop_file",args);
  assert.deepEqual(actual.matches,originalResult.matches);
  assert.deepEqual(actual.searchObservation.matchLocations.map(row=>row.line),[4,5,6,7,8,10]);
  const quality=Object.fromEntries(Object.keys(QUALITY).map(field=>[field,"隔离回放只核已发生的搜索元数据，不签发正文语义验收。"]));
  const assessment=await h.assess(reviewer,{...quality,method:originalReceipt.qualityChecks.method.basis,
    detail:originalReceipt.qualityChecks.detail.basis,revise:[],unlisted:[],unverifiedSources:[],
    goalFit:{pass:true,basis:"仅回放工具元数据；不将此合成判断计为原稿语义验收。"},
    sourceRefs:[{file:"sources/github-checks.md",start:6,end:8},{file:"sources/nist-scatter.md",start:6,end:6},
      {file:"sources/synthetic.md",start:1,end:5}]});
  const observed=assessment.searchObservations.entries[0];
  assert.equal(observed.query,undefined);assert.equal(observed.querySha256,digest(Buffer.from(args.query,"utf8")));
  assert.deepEqual(observed.requestedPaths,["module/candidate.md"]);
  assert.equal(observed.returnedMatches,6);assert.equal(observed.complete,true);assert.equal(observed.currentMaterial,true);
  assert.ok(!JSON.stringify(assessment.searchObservations).includes(args.query));
  assert.ok(!JSON.stringify(assessment.searchObservations).includes(actual.matches[0].text));
  output={spec:"building-loop-search-observation-replay/1",passed:true,identity:"review-agent:/root/causal_design",paidCalls:0,
    original:{run:"20261110T032313Z",arm:"fresh",callEventLine:874,resultEventLine:875,callId:call.data.callId,
      actualArgs:args,candidateSha256:digest(fs.readFileSync(path.join(workspace,args.path))),
      receiptSha256:digest(fs.readFileSync(path.join(workspace,"records/audit-final.json"))),
      inaccurateModelBasis:{method:originalReceipt.qualityChecks.method.basis,detail:originalReceipt.qualityChecks.detail.basis}},
    replay:{originalMatchesExactlyEqual:true,searchObservation:actual.searchObservation,
      exportedSearchObservations:assessment.searchObservations,assessmentProvenance:assessment.assessmentProvenance},
    boundaries:["Uses actual production handler in an isolated host-contract fixture; no real model or DSH SDK process was called.",
      "Original call was final-review; replay uses first-review with identical read scope and final frozen bytes.",
      "No original artifact changed and no semantic acceptance is claimed. Wrong prose remains explicitly model-assessed; host metadata separately proves the actual search path.",
      "Public receipt metadata contains no query literal or matching line text; this isolated validation retains the actual original call for reproduction."],
    code:{indexSha256:digest(fs.readFileSync(fileURLToPath(new URL("../../building-loop/governance/index.mjs",import.meta.url))))}};
});
fs.writeFileSync(fileURLToPath(new URL("replay-result.json",import.meta.url)),JSON.stringify(output,null,2)+"\n");
console.log(JSON.stringify({passed:output.passed,actualPath:output.replay.searchObservation.requestedPaths,
  matches:output.replay.searchObservation.returnedMatches,paidCalls:0}));

/** Read-only replay of the original 053234Z statistical clauses. */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import readline from "node:readline";
import { fileURLToPath, pathToFileURL } from "node:url";
import * as current from "../building-loop/governance/coverage.mjs";
import { authority, digest, keyOf } from "../building-loop/governance/policy.mjs";
import { lineList } from "../building-loop/governance/preflight.mjs";

const priorRun="20261110T053234Z";
const root=fileURLToPath(new URL("../../outputs/building-loop-efficiency-audit/"+priorRun+"/",import.meta.url));
const priorModule=path.join(root,"isolated-home/profiles/web/node_modules/dsh-building-loop/governance/coverage.mjs");
const prior=await import(pathToFileURL(priorModule));
const workspace=path.join(root,"reuse/workspace"),candidate=path.join(workspace,"module/candidate.md");
const bytes=fs.readFileSync(candidate),candidateSha256=digest(bytes);
assert.equal(candidateSha256,"cbf93253b49e4685c103411d459db079c6f0bb845aa5216911c239313439c971");

/** Instantiate only the proof contract in memory over the frozen source files. */
function replay(module,actor) {
  const phase="final-review",policy=authority(workspace),spec=policy.units.K01,reads=spec.phases[phase].read;
  const seen={};
  for(const file of reads) {
    const target=path.join(workspace,file);
    if(!fs.existsSync(target)||!fs.statSync(target).isFile())continue;
    const observed=fs.readFileSync(target);
    seen[keyOf(file)]={hash:digest(observed),ranges:[[1,lineList(observed).length]]};
  }
  const active={phase,seen},frame={root:workspace,policy,reads,agent:{id:actor}};
  const call=(action,args={})=>module.coverageAction(frame,active,spec,{action,...args});
  const blocks=call("inventory",{count:24}).blocks.filter(row=>row.line===13);
  assert.equal(blocks.length,2);
  assert.equal(blocks[0].id,"B16-68820bbd");
  return {call,frame,spec,blocks};
}

const input={kind:"direct",status:"supported",sourceRelation:"supports",basis:"核对本稿的实际引用行和同行标记。"};
const source="sources/synthetic.md";
const old=replay(prior,"prior-review");
const updated=replay(current,"updated-review");
const record=(r,block,part)=>r.call("record",{entries:[{block:r.blocks[block].id,parts:[part]}]});
const errorOf=action=>{try{action();assert.fail("expected an error");}catch(error){if(error.code==="ERR_ASSERTION")throw error;return error.message;}};

// Use exact past model calls, not a reconstruction of what the model might have
// sent. The archived tool errors also check our replay has the same boundary.
async function readEvents(directory,eventLines) {
  const selected=new Map();
  const stream=readline.createInterface({input:fs.createReadStream(path.join(directory,"events.jsonl")),crlfDelay:Infinity});
  let eventLine=0;
  for await(const line of stream) {
    eventLine++;
    if(eventLines.includes(eventLine))selected.set(eventLine,JSON.parse(line));
    if(eventLine===eventLines.at(-1))break;
  }
  return selected;
}
const selected=await readEvents(root,[1067,1145,1146]);
const readArgs=line=>JSON.parse(selected.get(line).data.arguments);
const firstArgs=readArgs(1145),wrongDomainArgs=readArgs(1067);
const priorHeadError=errorOf(()=>old.call("record",firstArgs));
assert.equal("Error: "+priorHeadError,selected.get(1146).data.message.content[0].text);
assert.match(priorHeadError,/只证明当前稿件的明确结构/);
const priorWholeBlock=record(old,0,{...input,objectCheck:{kind:"candidate",check:"citation-count",source,expected:6}});
assert.deepEqual(priorWholeBlock.recorded,[old.blocks[0].id]);
const incompleteLegacy=old.call("status",{block:old.blocks[0].id}).record.parts[0].objectCheck.result;
assert.equal(incompleteLegacy.matches,true);
assert.equal(incompleteLegacy.claimedLines,undefined);
assert.ok(old.call("record",wrongDomainArgs).recorded.includes(old.blocks[1].id));
const wrongDomainReplay=updated.call("record",wrongDomainArgs);
const updatedWrongDomainError=wrongDomainReplay.invalid.find(row=>row.block===updated.blocks[1].id)?.error;
assert.match(updatedWrongDomainError,/objectCheckHint/);

for(const [index,block] of updated.blocks.entries()) {
  assert.deepEqual(block.objectCheckHint,{kind:"candidate",check:"citation-profile",source});
  const args=index===0?structuredClone(firstArgs):structuredClone(wrongDomainArgs);
  args.entries=args.entries.filter(entry=>entry.block===block.id);
  const part=args.entries[0].parts.at(-1);
  delete part.evidence;
  part.objectCheck=block.objectCheckHint;
  assert.deepEqual(updated.call("record",args).recorded,[block.id]);
}
const accepted=updated.blocks.map(block=>updated.call("status",{block:block.id}).record);
current.requireStoredObjectChecks(updated.frame,updated.spec,[{records:accepted}],bytes);
const proofs=accepted.map(record=>({block:record.block,proof:record.parts.at(-1).objectCheck}));
assert.deepEqual(proofs.map(row=>row.proof.result.lines),[[4,5,6,7,8,10],[5,6,7,8]]);
assert.equal(digest(fs.readFileSync(candidate)),candidateSha256);

// An initial 0.7.5 paid draft actually submitted shifted ordinals. The shared
// preflight predicate must report both issues on its unchanged recorded bytes.
const preliminaryRun="20261110T062547Z",writeLine=338;
const preliminaryRoot=fileURLToPath(new URL("../../outputs/building-loop-efficiency-audit/"+preliminaryRun+"/",import.meta.url));
const preliminaryWrite=(await readEvents(preliminaryRoot,[writeLine])).get(writeLine);
assert.equal(preliminaryWrite.type,"tool/call");
assert.equal(preliminaryWrite.data.name,"building_loop_file");
const write=JSON.parse(preliminaryWrite.data.arguments);
assert.equal(write.action,"write");assert.equal(write.path,"module/candidate.md");
const preliminaryBytes=Buffer.from(write.content);
const preflight=current.candidateCitationProfiles(preliminaryBytes,[source],write.path);
assert.deepEqual(preflight.map(row=>row.matches),[false,false]);
assert.deepEqual(preflight.map(row=>row.lines),[[7,9,10,11,12,14],[9,10,11,12]]);
assert.deepEqual(preflight.map(row=>row.claimedLines),[[6,8,9,10,11,13],[8,9,10,11]]);

console.log(JSON.stringify({run:priorRun,candidateSha256,physicalLine:13,originalCandidateUnchanged:true,
  priorRuntimeSha256:digest(fs.readFileSync(priorModule)),updatedRuntimeSha256:digest(fs.readFileSync(new URL("../building-loop/governance/coverage.mjs",import.meta.url))),
  before:{events:{markerBlockCall:1067,headCall:1145,headError:1146},headError:priorHeadError,
    wholeBlockLegacyPartialMeasurement:incompleteLegacy,markerBlockWrongDomainAccepted:true},
  after:{markerBlockWrongDomainError:updatedWrongDomainError,closureObjectRecheck:true,proofs},
  preliminaryPreflightReplay:{run:preliminaryRun,writeEventLine:writeLine,candidateSha256:digest(preliminaryBytes),checks:preflight}},null,2));

import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { pathToFileURL } from "node:url";

const workspace = path.resolve(process.argv[2] ?? process.cwd());
const resultFile = process.argv[3];
const repo = path.join(workspace, "work/building-loop");
const run = path.join(workspace, "outputs/building-loop-efficiency-audit/20261110T063221Z");
const rawEvents = fs.readFileSync(path.join(run, "events.jsonl"));
const events = rawEvents.toString("utf8").trimEnd().split(/\r?\n/u).map(line => JSON.parse(line));
const digest = bytes => createHash("sha256").update(bytes).digest("hex");
const candidateSha256 = "75d74a752b36e5802451aad3104596dd88774433980fef846fbde332d2e1fb3f";
const blockId = "B10-1aa3ca1c";
const baseline = "ebe0b0cc05c64a2fec2be074b4e601d1b2e5c963";
const write = events[333];
const call = events[489];
assert.equal(write.data.name, "building_loop_file");
assert.equal(call.data.name, "building_loop_coverage");
assert.equal(events[508].type, "tool/result");
const draft = JSON.parse(write.data.arguments).content;
const entries = JSON.parse(call.data.arguments).entries;
const oldEntry = entries.find(entry => entry.block === blockId);
assert.equal(digest(draft), candidateSha256);
assert.ok(oldEntry.parts.some(part => part.finding?.kind === "invalid-inference" && part.status === "unsupported"));

const temporaryParent = fs.realpathSync(os.tmpdir());
const temp = fs.mkdtempSync(path.join(temporaryParent, "r076-bounded-"));
try {
  const historical = path.join(temp, "historical");
  const candidate = path.join(temp, "case");
  fs.mkdirSync(historical);
  // Keep the historical runtime separate from the current module graph so the
  // same archived candidate and actual old input exercise both entry points.
  for (const name of fs.readdirSync(path.join(repo, "governance")).filter(name => name.endsWith(".mjs"))) {
    const bytes = execFileSync("git", ["-C", repo, "show", `${baseline}:governance/${name}`]);
    fs.writeFileSync(path.join(historical, name), bytes);
  }
  fs.cpSync(path.join(run, "fresh/workspace"), candidate, { recursive: true });
  fs.writeFileSync(path.join(candidate, "module/candidate.md"), draft);

  async function setup(directory) {
    const code = await import(pathToFileURL(path.join(directory, "coverage.mjs")).href);
    const policy = await import(pathToFileURL(path.join(directory, "policy.mjs")).href);
    const { lineList } = await import(pathToFileURL(path.join(directory, "preflight.mjs")).href);
    const authority = policy.authority(candidate);
    const spec = authority.units.K01;
    const frame = { root: candidate, policy: authority, agent: { id: call.sid }, reads: spec.phases["final-review"].read };
    const active = { phase: "final-review", seen: {} };
    for (const file of frame.reads) {
      const bytes = fs.readFileSync(path.join(candidate, file));
      active.seen[policy.keyOf(file)] = { hash: digest(bytes), ranges: [[1, lineList(bytes).length]] };
    }
    const invoke = (action, args = {}) => code.coverageAction(frame, active, spec, { action, ...args });
    const inventory = invoke("inventory", { count: 24 });
    assert.equal(inventory.candidateSha256, candidateSha256);
    return { invoke, inventory };
  }

  const old = await setup(historical);
  const oldResult = old.invoke("record", { entries: [oldEntry] });
  assert.equal(oldResult.rejected.length, 1);
  assert.equal(oldResult.rejected[0].block, blockId);

  const current = await setup(path.join(repo, "governance"));
  let rejection;
  try {
    current.invoke("record", { entries: [oldEntry] });
  } catch (error) {
    rejection = error.message;
  }
  assert.match(rejection, /coverage-non-entailment.*不能说明.*只改核验状态/u);
  assert.equal(current.invoke("status").rejected.length, 0);

  const reviewed = structuredClone(oldEntry);
  const part = reviewed.parts.find(row => row.finding?.kind === "invalid-inference");
  part.status = "supported";
  part.sourceRelation = "supports";
  part.basis = "同一有界单向规则与样本事实允许其他复核对象属于该类别，也允许不属于。";
  delete part.finding;
  delete part.inference;
  const newResult = current.invoke("record", { entries: [reviewed] });
  const saved = current.invoke("status", { block: blockId }).record.parts.find(row => row.inference?.nonEntailment);
  assert.deepEqual(newResult.recorded, [blockId]);
  assert.equal(newResult.rejected.length, 0);
  assert.ok(saved.inference.nonEntailment.holds);
  assert.equal(digest(fs.readFileSync(path.join(candidate, "module/candidate.md"))), candidateSha256);

  const output = {
    passed: true, run: "20261110T063221Z", candidateSha256, eventsSha256: digest(rawEvents), blockId,
    historical: { commit: baseline, candidateWriteCallLine: 334, candidateWriteResultLine: 335, actualToolCallLine: 490, originalRejectResultLine: 509,
      argumentsSha256: digest(call.data.arguments), rejected: oldResult.rejected[0] },
    current: { moduleSha256: digest(fs.readFileSync(path.join(repo, "governance/coverage.mjs"))),
      unchangedInputError: rejection, debtAfterFalseReturn: 0, correctedReviewOnly: newResult.recorded,
      originalDraftUnchanged: true, proof: saved.inference },
  };
  if (resultFile) fs.writeFileSync(resultFile, JSON.stringify(output, null, 2) + "\n");
  process.stdout.write(JSON.stringify({ passed: true, blockId, oldRejected: 1, currentRejected: 0 }) + "\n");
} finally {
  assert.equal(path.dirname(fs.realpathSync(temp)), temporaryParent);
  assert.ok(path.basename(temp).startsWith("r076-bounded-"));
  fs.rmSync(temp, { recursive: true, force: true });
}

import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { fileURLToPath, pathToFileURL } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const workspace = path.resolve(here, "../..");
const repo = path.join(workspace, "work/building-loop");
const run = path.join(workspace, "outputs/building-loop-efficiency-audit/20261110T063219Z");
const original = path.join(run, "reuse/workspace");
const prior = path.join(run, "isolated-home/profiles/web/node_modules/dsh-building-loop");
const sourceNames = ["AGENTS.md", "DISPATCH.md", "BUILDING-LOOP.json", "module/INDEX.md",
  "sources/github-checks.md", "sources/nist-scatter.md", "sources/synthetic.md", "sources/source-checks.json"];
const hash = value => createHash("sha256").update(value).digest("hex");
const read = file => fs.readFileSync(file);
const seed = read(path.join(run, "seed-candidate.md"));
const raw = read(path.join(run, "events.jsonl"));
const events = raw.toString("utf8").trimEnd().split(/\r?\n/u).map((line, i) => ({ ...JSON.parse(line), line: i + 1 }));
const calls = new Map(events.filter(event => event.type === "tool/call").map(event => [event.data.callId, event]));
const rawErrors = events.filter(event => event.type === "tool/result"
  && event.data.message.content.some(block => block.text?.includes("C4 的事实退回须 finding.kind")));
assert.equal(rawErrors.length, 10);
const history = rawErrors.map(event => {
  const call = calls.get(event.data.message.toolCallId);
  assert.ok(call && call.sid === event.sid && call.data.name === "building_loop");
  const args = JSON.parse(call.data.arguments);
  const check = args.checks.find(row => row.id === "C4");
  assert.equal(args.action, "review");
  return { callLine: call.line, resultLine: event.line, callId: call.data.callId, inputSha256: hash(call.data.arguments), args, check };
});
const firstAttempt = history[0];
const reviewerSid = calls.get(firstAttempt.callId).sid;
const priorProofs = events.filter(event => event.sid === reviewerSid && event.line < firstAttempt.callLine && event.type === "tool/result"
  && !event.data.message.isError).flatMap(event => {
  const call = calls.get(event.data.message.toolCallId);
  if (call?.data.name !== "building_loop_coverage") return [];
  const args = JSON.parse(call.data.arguments);
  return args.action === "record" ? [args] : [];
});

/** Use the real registered handlers from both exact source snapshots. Every
 * historical request is replayed against the same initial phase and proofs. */
async function replay(packageRoot, attempt) {
  const { fixture, host } = await import(pathToFileURL(path.join(packageRoot, "test/helpers.mjs")));
  let result;
  await fixture(async (root, write) => {
    for (const name of sourceNames) {
      fs.mkdirSync(path.dirname(path.join(root, name)), { recursive: true });
      write(name, read(path.join(original, name)));
    }
    write("module/candidate.md", seed);
    write("PROJECT.md", read(path.join(run, "goal-before.md")));
    fs.mkdirSync(path.join(root, "records"));
    const h = host(root, { automaticCoverage: false });
    await h.flow("root", "prepare");
    const executor = (await h.flow("root", "advance")).childId;
    await h.flow(executor, "prepare");
    await h.flow(executor, "submit");
    const reviewer = (await h.flow("root", "advance")).childId;
    await h.flow(reviewer, "prepare");
    const inventory = await h.coverage(reviewer, "inventory", { count: 24 });
    assert.equal(inventory.blocks.length, inventory.total);
    for (const args of priorProofs) await h.coverage(reviewer, args.action, args);
    assert.deepEqual((await h.coverage(reviewer, "status")).pending, []);
    try {
      const decision = await h.flow(reviewer, "review", attempt.args);
      const receipt = JSON.parse(read(path.join(root, "records/audit-first.json")));
      result = { passedParameterGate: true, phase: decision.phase, candidateSha256: receipt.candidateSha256,
        pendingCoverage: receipt.coverage.pending, check: receipt.checks.find(row => row.id === "C4") };
    } catch (error) {
      result = { passedParameterGate: false, error: error.message,
        phase: (await h.flow("root", "status")).units[0].phase, receiptCreated: fs.existsSync(path.join(root, "records/audit-first.json")) };
    }
  });
  return result;
}

const rows = [];
for (const attempt of history) {
  const before = await replay(prior, attempt);
  const after = await replay(repo, attempt);
  assert.equal(before.phase, "first-review");
  assert.match(before.error, /C4 的事实退回须/u);
  if (attempt.check.finding) {
    assert.equal(after.phase, "supplement-ready");
    assert.deepEqual(after.pendingCoverage, []);
    assert.equal(after.candidateSha256, hash(seed));
    assert.equal(after.check.finding.quote, attempt.check.finding.quote.slice("- C4：".length));
    assert.equal(after.check.line, 13);
  } else {
    assert.equal(after.phase, "first-review");
    assert.equal(after.receiptCreated, false);
    assert.match(after.error, /unsupported 须提供 finding\.kind.*候选第 13 行正文/u);
  }
  rows.push({ callLine: attempt.callLine, resultLine: attempt.resultLine, callId: attempt.callId,
    inputSha256: attempt.inputSha256, submittedC4: attempt.check, before, after });
}
const report = { passed: true, historicalRun: path.basename(run), eventsSha256: hash(raw), candidateSha256: hash(seed),
  historicalRuntimeSha256: hash(read(path.join(prior, "governance/index.mjs"))),
  currentRuntimeSha256: hash(read(path.join(repo, "governance/index.mjs"))),
  successfulHistoricalCoverageCallsReplayed: priorProofs.length, attempts: rows.length,
  exactCopiedHeadingsAccepted: rows.filter(row => row.after.passedParameterGate).length,
  missingFindingsStillRejected: rows.filter(row => !row.after.passedParameterGate).length, rows };
assert.equal(report.exactCopiedHeadingsAccepted, 7);
assert.equal(report.missingFindingsStillRejected, 3);
fs.writeFileSync(path.join(here, "r076-numbered-finding-replay-result.json"), JSON.stringify(report, null, 2) + "\n", "utf8");
process.stdout.write(JSON.stringify({ passed: report.passed, attempts: rows.length,
