import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { pathToFileURL } from "node:url";

// Replay the exact two model-written candidate versions through each runtime's
// registered tools. The synthetic intake only establishes the supplement role.
const root = process.cwd();
const run = path.join(root, "outputs/building-loop-efficiency-audit/20261110T063219Z");
const current = path.join(root, "work/building-loop");
const baseline = path.join(run, "isolated-home/profiles/web/node_modules/dsh-building-loop");
const eventBytes = fs.readFileSync(path.join(run, "events.jsonl"));
const events = eventBytes.toString("utf8").trimEnd().split(/\r?\n/u).map(JSON.parse);
const event = line => events[line - 1];
const args = line => JSON.parse(event(line).data.arguments);
const resultText = line => event(line).data.message.content[0].text;
const result = line => JSON.parse(resultText(line));
const sha256 = bytes => createHash("sha256").update(bytes).digest("hex");
const wrong = args(553);
const corrected = args(589);
const candidate = "module/candidate.md";
const source = "sources/synthetic.md";
assert.equal(wrong.path, candidate);
assert.equal(corrected.path, candidate);
assert.equal(sha256(wrong.content), result(554).sha256);
assert.equal(sha256(corrected.content), result(590).sha256);
assert.equal(result(560).ok, true);
assert.equal(result(596).ok, true);
assert.equal(result(560).citationProfileChecks, undefined);
assert.equal(result(596).citationProfileChecks, undefined);
assert.equal(result(566).sha256, result(554).sha256);
assert.equal(result(566).lines.length, result(566).totalLines);
assert.match(resultText(572), /组合稿件统计不符/u);
assert.equal(result(584).citationProfileChecks.candidateSha256, result(554).sha256);
assert.match(resultText(602), /完整读回当前候选/u);
assert.equal(result(608).sha256, result(590).sha256);
assert.equal(result(608).lines.length, result(608).totalLines);
assert.equal(result(615).phase, "final-review-ready");

async function replay(repo, expectedPending) {
  const { fixture, host, policy } = await import(pathToFileURL(path.join(repo, "test/helpers.mjs")));
  const { QUALITY } = await import(pathToFileURL(path.join(repo, "governance/preflight.mjs")));
  const observation = { indexSha256: sha256(fs.readFileSync(path.join(repo, "governance/index.mjs"))) };
  await fixture(async (workspace, write) => {
    fs.mkdirSync(path.join(workspace, "module"));
    fs.mkdirSync(path.join(workspace, "sources"));
    write(source, fs.readFileSync(path.join(run, "reuse/workspace", source)));
    write(candidate, "- C1：通过19/20（出处：functional.csv 第 2 行）。\n\n大白话：看实际记录。\n\n附录。\n");
    const authority = structuredClone(policy);
    const unit = authority.units.K01;
    unit.candidate = candidate;
    unit.claims = ["C1"];
    unit.calculations = {};
    unit.plainLast = true;
    for (const phase of Object.values(unit.phases)) {
      for (const grant of ["read", "write"]) {
        if (phase[grant]) phase[grant] = phase[grant].map(file => file === "candidate.md" ? candidate : file);
      }
    }
    unit.phases.supplement.read.push(source);
    unit.phases["final-review"].read.push(source);
    unit.phases["final-review"].evidence.push(source);
    write("BUILDING-LOOP.json", JSON.stringify(authority));
    const h = host(workspace);
    const intake = (await h.flow("root", "advance")).childId;
    await h.flow(intake, "prepare");
    await h.flow(intake, "submit");
    const reviewer = (await h.flow("root", "advance")).childId;
    await h.flow(reviewer, "prepare");
    const check = { id: "C1", status: "supported", file: "functional.csv", start: 2, end: 2,
      basis: "源记录明确写明通过19项，总数20项。" };
    await h.assess(reviewer, { ...Object.fromEntries(Object.keys(QUALITY).map(key => [key, "按授权数据复核实际样例并给出读者说明。"])),
      sourceRefs: [{ file: "functional.csv", start: 2, end: 2, quote: "19,20" }], unverifiedSources: [], unlisted: [],
      revise: [], goalFit: { pass: true, basis: "只核对本例记录。" } });
    assert.equal((await h.flow(reviewer, "review", { checks: [check] })).phase, "supplement-ready");
    const executor = (await h.flow("root", "advance")).childId;
    await h.flow(executor, "prepare");

    const preview = async (record, callLine) => {
      await h.file(executor, "write", candidate, { content: record.content, note: record.note });
      const output = await h.flow(executor, "preflight", args(callLine));
      assert.equal(output.ok, !expectedPending);
      assert.deepEqual(output.pendingRead, expectedPending ? { file: candidate, reason: "current-candidate-read-required" } : undefined);
      assert.equal(output.citationLineCounts, undefined);
      assert.equal(output.citationProfileChecks, undefined);
      return { ok: output.ok, pendingRead: output.pendingRead, issues: output.issues };
    };
    observation.wrongBeforeRead = await preview(wrong, 559);
    await h.file(executor, "read", candidate, { start: 1, count: 5 });
    const partial = await h.flow(executor, "preflight");
    assert.equal(partial.ok, !expectedPending);
    assert.equal(partial.citationProfileChecks, undefined);
    await assert.rejects(h.flow(executor, "submit", args(571)), /请先完整读回当前候选文件/u);
    await h.file(executor, "read", candidate);
    await assert.rejects(h.flow(executor, "submit", args(571)), /组合稿件统计不符/u);
    const wrongRead = await h.flow(executor, "preflight", args(583));
    assert.equal(wrongRead.ok, false);
    assert.deepEqual(wrongRead.citationProfileChecks, result(584).citationProfileChecks);
    observation.wrongAfterRead = { ok: wrongRead.ok, profileChecks: wrongRead.citationProfileChecks };
    observation.correctedBeforeRead = await preview(corrected, 595);
    await assert.rejects(h.flow(executor, "submit", args(601)), /请先完整读回当前候选文件/u);
    await h.file(executor, "read", candidate);
    const correctRead = await h.flow(executor, "preflight");
    assert.equal(correctRead.ok, true);
    assert.equal(correctRead.pendingRead, undefined);
    assert.equal(correctRead.citationProfileChecks.candidateSha256, result(590).sha256);
    assert.ok(correctRead.citationProfileChecks.clauses.every(row => row.matches));
    const submitted = await h.flow(executor, "submit", args(613));
    assert.equal(submitted.phase, result(615).phase);
    observation.correctedAfterRead = { ok: correctRead.ok, profileChecks: correctRead.citationProfileChecks, phase: submitted.phase };
  });
  return observation;
}

