import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { fileURLToPath, pathToFileURL } from "node:url";

const here=path.dirname(fileURLToPath(import.meta.url));
const workspace=path.resolve(here,"../..");
const repo=path.join(workspace,"work/building-loop");
const sourceNames=["AGENTS.md","DISPATCH.md","BUILDING-LOOP.json","module/INDEX.md",
  "sources/github-checks.md","sources/nist-scatter.md","sources/synthetic.md","sources/source-checks.json"];
const hash=value=>createHash("sha256").update(value).digest("hex");
const read=file=>fs.readFileSync(file);
const runtimeHash=root=>hash(read(path.join(root,"governance/index.mjs")));

/** Replay the original accepted coverage requests and then the unchanged
 * failed tool input on either exact production handler snapshot. */
async function replay(packageRoot,original,run,seed,proofs,reviewArgs) {
  const {fixture,host}=await import(pathToFileURL(path.join(packageRoot,"test/helpers.mjs")));
  let result;
  await fixture(async(root,write)=>{
    for(const name of sourceNames) {
      fs.mkdirSync(path.dirname(path.join(root,name)),{recursive:true});
      write(name,read(path.join(original,name)));
    }
    write("module/candidate.md",seed);
    write("PROJECT.md",read(path.join(run,"goal-before.md")));
    fs.mkdirSync(path.join(root,"records"));
    const h=host(root,{automaticCoverage:false});
    await h.flow("root","prepare");
    const executor=(await h.flow("root","advance")).childId;
    await h.flow(executor,"prepare");
    await h.flow(executor,"submit");
    const reviewer=(await h.flow("root","advance")).childId;
    const prepared=await h.flow(reviewer,"prepare");
    const inventory=await h.coverage(reviewer,"inventory",{count:24});
    assert.equal(inventory.blocks.length,inventory.total);
    for(const args of proofs)await h.coverage(reviewer,args.action,args);
    assert.deepEqual((await h.coverage(reviewer,"status")).pending,[]);
    try {
      const decision=await h.flow(reviewer,"review",reviewArgs);
      const receipt=JSON.parse(read(path.join(root,"records/audit-first.json")));
      result={phase:decision.phase,decision:receipt.decision,preparedClaims:prepared.claims,
        candidateSha256:receipt.candidateSha256,pendingCoverage:receipt.coverage.pending,
        check:receipt.checks.find(row=>row.id==="C4"),
        coverageFinding:receipt.coverage.rejected.find(row=>row.line===13)?.finding};
    } catch(error) {
      result={phase:(await h.flow("root","status")).units[0].phase,error:error.message,
        preparedClaims:prepared.claims,receiptCreated:fs.existsSync(path.join(root,"records/audit-first.json"))};
    }
  });
  return result;
}

const rows=[];
for(const [id,arm,locations] of [["20261110T085508Z","reuse",[182]],["20261110T085511Z","fresh",[136,142]]]) {
  const run=path.join(workspace,"outputs/building-loop-efficiency-audit",id);
  const original=path.join(run,arm,"workspace");
  const prior=path.join(run,"isolated-home/profiles/web/node_modules/dsh-building-loop");
  const seed=read(path.join(run,"seed-candidate.md"));
  const raw=read(path.join(run,"events.jsonl"));
  const events=raw.toString("utf8").trimEnd().split(/\r?\n/u).map((line,i)=>({...JSON.parse(line),line:i+1}));
  const calls=new Map(events.filter(event=>event.type==="tool/call").map(event=>[event.data.callId,event]));
  for(const resultLine of locations) {
    const event=events[resultLine-1];
    const call=calls.get(event.data.message.toolCallId);
    const args=JSON.parse(call.data.arguments);
    assert.equal(args.action,"review");
    assert.equal(event.data.message.isError,true);
    assert.match(event.data.message.content[0].text,/C4/u);
    const omitted=args.checks.find(check=>check.id==="C4")?"finding":"check";
    const proofs=events.filter(row=>row.line<call.line&&row.sid===call.sid&&row.type==="tool/result"&&!row.data.message.isError)
      .flatMap(row=>{
        const previous=calls.get(row.data.message.toolCallId);
        if(previous?.data.name!=="building_loop_coverage")return [];
        const input=JSON.parse(previous.data.arguments);
        return input.action==="record"?[input]:[];
      });
    const before=await replay(prior,original,run,seed,proofs,args);
    const after=await replay(repo,original,run,seed,proofs,args);
    assert.equal(before.phase,"first-review");
    assert.equal(before.receiptCreated,false);
    assert.match(before.error,/C4/u);
    assert.equal(after.phase,"supplement-ready");
    assert.equal(after.decision,"reject");
    assert.deepEqual(after.pendingCoverage,[]);
    assert.equal(after.candidateSha256,hash(seed));
    assert.equal(after.check.line,13);
    assert.equal(after.check.status,"unsupported");
    assert.equal(after.check.findingOrigin.kind,"same-reviewer-coverage");
    assert.deepEqual(after.check.finding,after.coverageFinding);
    rows.push({run:id,arm,omitted,eventsSha256:hash(raw),candidateSha256:hash(seed),runtimeBefore:runtimeHash(prior),
      inputSha256:hash(call.data.arguments),callLine:call.line,resultLine,successfulCoverageCalls:proofs.length,before,after});
  }
}
const result={passed:true,kind:"exact-recorded-numbered-review-omissions",runtimeAfter:runtimeHash(repo),rows};
fs.writeFileSync(path.join(here,"r077-review-omissions-replay.json"),JSON.stringify(result,null,2)+"\n","utf8");
process.stdout.write(JSON.stringify({passed:result.passed,attempts:rows.length,carried:rows.map(row=>row.omitted)})+"\n");

