import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { coverageSummary, sourceLineEnumerationChecks } from "../building-loop/governance/coverage.mjs";
import { authority, digest, keyOf } from "../building-loop/governance/policy.mjs";

// Replay both complete paid model proofs against the current gate. The old run
// stays immutable. Only this smoke report is written to the validation folder.
const directory = path.dirname(fileURLToPath(import.meta.url));
const run = "20261110T112244Z";
const runRoot = path.resolve(directory, "../../outputs/building-loop-efficiency-audit", run);
const root = path.join(runRoot, "reuse", "workspace");
const stateHome = path.join(runRoot, "isolated-home", "building-loop-state");
const stateFile = fs.readdirSync(stateHome).filter(file => file.endsWith(".json"))
  .map(file => path.join(stateHome, file)).find(file => JSON.parse(fs.readFileSync(file)).units?.K01);
assert.ok(stateFile);
const stateBytes = fs.readFileSync(stateFile);
const { proof } = JSON.parse(stateBytes).units.K01;
const receiptBytes = fs.readFileSync(path.join(root, "records", "audit-final.json"));
const receipt = JSON.parse(receiptBytes);
const policy = authority(root);
const spec = policy.units.K01;
const candidate = fs.readFileSync(path.join(root, spec.candidate));
const original = candidate.toString("utf8");
const repaired = Buffer.from(original.replace("在第 6 行列出的结论例子", "在第 7-8 行列出的结论例子"));
const originalRow = original.split("\n")[4];
const repairedRow = repaired.toString("utf8").split("\n")[4];
assert.equal(digest(candidate), receipt.candidateSha256);
assert.equal(receipt.decision, "accept");
assert.notEqual(originalRow, repairedRow);

const results = [];
for (const [role, phase, stored, ownReceipt, identity, recordEvents] of [
  ["reviewer", "final-review", proof.reviewerCoverage, receipt, receipt.reviewer, [465, 466]],
  ["auditor", "final-audit", proof.auditorCoverage, receipt.independentAudit, receipt.independentAudit.auditor, [563, 564]],
]) {
  const reads = spec.phases[phase].read;
  const seen = Object.fromEntries(ownReceipt.actualReads.map(row => [keyOf(row.file), { hash: row.sha256, ranges: row.ranges }]));
  const frame = { root, policy, role, reads, agent: { id: identity } };
  const active = { phase, seen, coverage: { ...stored, records: Object.fromEntries(stored.records.map(row => [row.block, row])) } };
  const result = coverageSummary(frame, active, spec);
  assert.equal(result.records.length, 23);
  assert.deepEqual(result.pending, []);
  assert.equal(result.rejected.length, 1);
  const [debt] = result.rejected;
  const originalRecord = result.records.find(row => row.block === debt.block);
  assert.equal(originalRecord.parts[0].status, "supported");
  assert.deepEqual(debt, result.rejected.find(row => row.sourceLineEnumeration?.matches === false));
  assert.deepEqual(debt.sourceLineEnumeration.missing, ["failure", "success"]);
  assert.deepEqual([debt.sourceLineEnumeration.source.start, debt.sourceLineEnumeration.source.end], [6, 6]);
  assert.deepEqual([debt.sourceLineEnumeration.locator.start, debt.sourceLineEnumeration.locator.end], [6, 8]);
  const positive = sourceLineEnumerationChecks(frame, active, spec, repaired);
  assert.equal(positive.length, 1);
  assert.deepEqual([positive[0].source.start, positive[0].source.end, positive[0].matches, positive[0].missing], [7, 8, true, []]);
  const noReads = sourceLineEnumerationChecks(frame, { ...active, seen: {} }, spec, candidate);
  assert.deepEqual(noReads, []);
  results.push({
    role, phase, identity, args: { reads, seen, originalRecord, recordEvents, complete: true,
      storedCoverageSha256: digest(JSON.stringify(stored)), priorRecordCount: stored.records.length },
    result: { currentCandidateSha256: result.candidateSha256, currentModelRecordCount: result.records.length,
      pending: result.pending, rejected: [debt], repairedEnumeration: positive, noReadEnumeration: noReads },
  });
}

const summary = { spec: "building-loop-two-role-coverage-replay/1", passed: true, run,
  runtimeCoverageSha256: digest(fs.readFileSync(path.resolve(directory, "../building-loop/governance/coverage.mjs"))),
  sourceRunArgs: { stateSha256: digest(stateBytes), receiptSha256: digest(receiptBytes), policySha256: policy.hash,
    candidateSha256: digest(candidate), repairedCandidateSha256: digest(repaired), originalRow, repairedRow },
  results };
const output = path.join(directory, "r077-source-line-enumeration-both-role-smoke.json");
fs.writeFileSync(output, JSON.stringify(summary, null, 2) + "\n");
console.log(JSON.stringify({ passed: true, roles: results.map(row => row.role), reportSha256: digest(fs.readFileSync(output)) }));

