import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { classificationDisagreements, CLASSIFICATION_VERSION, neutralTextSpans, recordMeetsDispute } from "../building-loop/governance/coverage.mjs";
import { digest } from "../building-loop/governance/policy.mjs";

const folder = path.dirname(fileURLToPath(import.meta.url));
const run = path.resolve(folder,"../../outputs/building-loop-efficiency-audit/20261110T120459Z");
const oldFile = path.join(run,"isolated-home/profiles/web/node_modules/dsh-building-loop/governance/coverage.mjs");
const old = await import(pathToFileURL(oldFile));
const evidence = JSON.parse(fs.readFileSync(path.join(folder,"r077-seventh-reuse-supplement-label-blocked.json")));
const {targetedPrepare,roleCheckpoints,failedTargetedEntries,blockTransition}=evidence.reconciliation;
assert.equal(blockTransition.output.phase,"blocked");
const accepted = roleCheckpoints.reviewerCheckpoint.exactRecord;
const dispute = targetedPrepare.disputes[0];
const failed = failedTargetedEntries[0].exactEntry;
assert.equal(failed.block,accepted.block);
assert.equal(dispute.block,accepted.block);
// The failed call's pieces are exactly the candidate bytes. Reconstruct the
// offsets that reviewBlock would store before evaluating the old dispute.
let cursor=0;
const parts=failed.parts.map(part=>{
  const start=accepted.text.indexOf(part.quote,cursor);
  assert.ok(start>=cursor&&!accepted.text.slice(cursor,start).trim());
  cursor=start+part.quote.length;
  return {...part,start,end:cursor};
});
assert.equal(cursor,accepted.text.length);
const attempted={...accepted,parts};
assert.equal(old.recordMeetsDispute(attempted,dispute),false);
assert.equal(recordMeetsDispute(attempted,dispute),true);
const candidateSha256=evidence.candidateSha256;
const reviewer={candidateSha256,records:[accepted]},auditor={candidateSha256,records:[attempted]};
const before = old.classificationDisagreements(reviewer,auditor);
assert.equal(before.length,1);
assert.match(before[0].text,/^- \[补充\]/u);
assert.deepEqual(before[0].factualSpans,[[3,7]]);
const after = classificationDisagreements(reviewer,auditor);
assert.deepEqual(after,[]);

// Different factual classifications after the title still require resolution.
const withChangedBody = structuredClone(auditor);
const body = withChangedBody.records.find(record=>record.block===before[0].block);
const detail = body.parts.find(part=>part.kind==="direct"&&part.end>8);
assert.ok(detail);
detail.kind="nonfactual";
const remaining = classificationDisagreements(reviewer,withChangedBody);
assert.ok(remaining.some(row=>row.factualSpans.some(([,end])=>end>8)));
assert.deepEqual(neutralTextSpans("正文提到 [补充]，并作了新断言。"),[]);
const result = {passed:true,run:"20261110T120459Z",candidateSha256,oldTargetedRecordAccepted:false,currentTargetedRecordAccepted:true,
  runtimeBefore:digest(fs.readFileSync(oldFile)),classificationBefore:old.CLASSIFICATION_VERSION,
  runtimeAfter:digest(fs.readFileSync(path.resolve(folder,"../building-loop/governance/coverage.mjs"))),
  classificationAfter:CLASSIFICATION_VERSION,before,after,changedBodyStillDisputed:remaining};
fs.writeFileSync(path.join(folder,"r077-supplement-label-replay.json"),JSON.stringify(result,null,2)+"\n");
console.log(JSON.stringify({passed:true,oldDisputes:before.length,currentDisputes:after.length,changedBodyDisputes:remaining.length}));

import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { createHash } from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { withWorkspaceLock } from "../building-loop/governance/transactions.mjs";

assert.equal(process.platform, "win32");
const parent = fs.realpathSync.native(os.tmpdir());
const home = fs.mkdtempSync(path.join(parent, "bl-native-share-probe-"));
const create = fs.mkdtempSync, rename = fs.renameSync;
const ready = path.join(home, "helper.ready"), release = path.join(home, "helper.release");
const released = path.join(home, "helper.released");
const wait = new Int32Array(new SharedArrayBuffer(4));
const errors = [];
let helper;
let ran = false;

// Hold the actual claim directory with the Win32 delete share deliberately off.
// Release only after the original Node rename has failed, without injecting an errno.
const script = `import ctypes, pathlib, sys, time
from ctypes import wintypes
k = ctypes.WinDLL('kernel32', use_last_error=True)
k.CreateFileW.argtypes = [wintypes.LPCWSTR,wintypes.DWORD,wintypes.DWORD,ctypes.c_void_p,wintypes.DWORD,wintypes.DWORD,wintypes.HANDLE]
k.CreateFileW.restype = wintypes.HANDLE
k.CloseHandle.argtypes = [wintypes.HANDLE]
h = k.CreateFileW(sys.argv[1],0x80000000,3,None,3,0x02000000,None)
if h == wintypes.HANDLE(-1).value: raise ctypes.WinError(ctypes.get_last_error())
try:
    pathlib.Path(sys.argv[2]).touch()
    deadline = time.monotonic() + 5
    while not pathlib.Path(sys.argv[3]).exists() and time.monotonic() < deadline:
        time.sleep(.01)
finally:
    k.CloseHandle(h)
    pathlib.Path(sys.argv[4]).touch()`;

function awaitMarker(marker) {
  const deadline = Date.now() + 2000;
  while (!fs.existsSync(marker) && Date.now() < deadline) Atomics.wait(wait, 0, 0, 10);
  assert.equal(fs.existsSync(marker), true, path.basename(marker));
}

try {
  fs.mkdtempSync = (prefix, ...args) => {
    const dir = create(prefix, ...args);
    if (prefix === path.join(home, "state.json.claim-")) {
      helper = spawn("python", ["-X", "utf8", "-B", "-c", script, dir, ready, release, released], { stdio: "ignore" });
      awaitMarker(ready);
    }
    return dir;
  };
  fs.renameSync = (from, to) => {
    try { return rename(from, to); }
    catch (error) {
      if (to === path.join(home, "state.json.lock")) {
        errors.push({ code: error.code, syscall: error.syscall });
        fs.closeSync(fs.openSync(release, "w"));
        awaitMarker(released);
      }
      throw error;
    }
  };
  withWorkspaceLock(home, "state.json", () => { ran = true; });
  assert.equal(errors.length, 1);
  assert.equal(ran, true);
  assert.deepEqual(fs.readdirSync(home).sort(), ["helper.ready", "helper.release", "helper.released"]);
  const runtime = fs.readFileSync(new URL("../building-loop/governance/transactions.mjs", import.meta.url));
  console.log(JSON.stringify({ passed: true, platform: process.platform, node: process.version,
    runtimeSha256: createHash("sha256").update(runtime).digest("hex"),
    setup: "Separate Win32 process holds the staged directory without FILE_SHARE_DELETE until its real rename fails",
    realRenameErrors: errors, operationEntered: ran, stagingAndLockCleaned: true }, null, 2));
} finally {
  fs.mkdtempSync = create;
  fs.renameSync = rename;
  if (helper && helper.exitCode === null) await new Promise(resolve => helper.once("exit", resolve));
  assert.equal(path.dirname(fs.realpathSync.native(home)), parent);
  assert.match(path.basename(home), /^bl-native-share-probe-/u);
  fs.rmSync(home, { recursive: true });
}

